    /** The next number on a sheet, locked by the caller, for a claim due by this day arriving there now, as
     *  {@link #nextNumber(Sheet, LocalDate)} gives it. */
    public String nextNumberOn(Sheet sheet, LocalDate dueBy) {
        return nextNumber(sheet, dueBy);
    }

    /** The next number for a claim due by this day, opened now: within its period (<period name>-<n>, or X-<n>
     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
    private String nextNumber(Sheet sheet, LocalDate date) {
        if (!sheet.numbersPerPeriod()) {
            return String.valueOf(sheet.nextClaimNumber());
        }
        String prefix = prefixOn(sheet, date);
        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
        String number = sequence.next();
        sequences.save(sequence);
        return number;
    }

    /** The prefix of the numbers given within the period a day is in: its name, or X in no period. */
    private String prefixOn(Sheet sheet, LocalDate date) {
        return periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
    }

    /** Refuse to settle or approve a claim with no proofs whose due is above the proof threshold in force on its
     *  date for its person's grade then (a claim with no due, or with no threshold then, needs none). */
        return noteThresholdOn(today);
    }

    /** A person's due-total is at most this (two decimals), in force on the sheet's today; null means none. */
    public BigDecimal getCap() {
        return amountOn(CAP, today, null);
    }

    /** A person's due-total as it counts: the sum of their figures, at most the cap when there is one. */
    public BigDecimal capped(BigDecimal sum) {
        BigDecimal cap = getCap();
        return cap == null || sum.compareTo(cap) <= 0 ? sum : cap;
    }

    /** Whether a claim opened now is numbered within its period: the period numbering from is set and the
     *  sheet's today is on or after it. */
    public boolean numbersPerPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** How a claim's figures round when the claim (or, for a correction, the claim it corrects) is dated on this
     *  day: half up before the policy date (the sheet's today when it has none), half to even on or after it. */
    public RoundingMode roundingFor(LocalDate date) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Take the next claim number on this sheet; it is never given out again. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }

    /** The number of the last settle batch on this sheet; 0 when there has been none. */
    public int getLastSettleBatch() {
        return lastSettleBatch;
    }

    public void setLastSettleBatch(int lastSettleBatch) {
        this.lastSettleBatch = lastSettleBatch;
    }

    /** Take the next settle batch number on this sheet. */
    public int nextSettleBatch() {
        return ++lastSettleBatch;
    }
}
